<script lang="ts">
 import { onMount } from 'svelte';import { Button } from '@hasbai/ui/button';import { Input } from '@hasbai/ui/input';import { Moon,Sun } from '@lucide/svelte';import { DEFAULT_SETTINGS, type Settings } from '../../shared/types';import type { Api } from '../lib/api';
 let {api,dark=false,ontheme=()=>{}}:{api:Api;dark?:boolean;ontheme?:()=>void}=$props();let settings=$state<Settings>({...DEFAULT_SETTINGS}),loading=$state(true),busy=$state(false),error=$state(''),saved=$state(false),loaded=$state(false);
 onMount(()=>{void load();});async function load(){loading=true;error='';try{settings=await api.request<Settings>('settings');loaded=true;}catch(e){error=(e as Error).message;}finally{loading=false;}}
 async function save(){busy=true;error='';saved=false;try{settings=await api.request<Settings>('settings','PUT',settings);saved=true;}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<header class="page-head"><div><p class="eyebrow">YOUR IDENTITY</p><h1>对话设置</h1></div><Button variant="outline" onclick={ontheme} aria-label={dark?'切换浅色模式':'切换深色模式'}>{#if dark}<Sun size={18}/>{:else}<Moon size={18}/>{/if}主题</Button></header>
{#if error}<p class="error" role="alert">{error}<Button variant="outline" onclick={load}>重试</Button></p>{/if}{#if loading}<div class="empty" role="status">正在加载设置…</div>{:else if loaded}<form class="settings-form" onsubmit={e=>{e.preventDefault();void save();}}><div class="field"><label for="user-name">你的名字</label><Input id="user-name" bind:value={settings.userName} required maxlength={80}/></div><div class="field"><label for="persona">你的角色设定</label><textarea id="persona" bind:value={settings.persona} rows="5" maxlength={12000}></textarea></div><div class="field"><label for="system-prompt">系统提示</label><textarea id="system-prompt" bind:value={settings.systemPrompt} rows="5" required maxlength={12000}></textarea></div><div class="two-fields"><div class="field"><label for="temperature">温度</label><Input id="temperature" type="number" min="0" max="2" step="0.1" bind:value={settings.temperature} required/></div><div class="field"><label for="max-tokens">回复长度上限</label><Input id="max-tokens" type="number" min="128" max="4096" step="1" bind:value={settings.maxTokens} required/></div></div><div class="actions"><Button type="submit" disabled={busy}>{busy?'保存中…':'保存设置'}</Button>{#if saved}<span role="status">已保存</span>{/if}</div></form>{/if}
